import Differentiation
import Foundation

@differentiable(reverse)
private func atan2d(_ y: Float, _ x: Float) -> Float {
    return atan2(y, x)
}

@derivative(of: atan2d)
private func vjpAtan2d(_ y: Float, _ x: Float) -> (value: Float, pullback: (Float) -> (Float, Float)) {
    let value = atan2(y, x)
    let denom = (x * x) + (y * y)
    return (value, { v in
        let scale = v / denom
        return (scale * x, scale * -y)
    })
}

@differentiable(reverse)
private func unsafeBufferSumAD(_ values: [Float]) -> Float {
    values.withUnsafeBufferPointer { buffer in
        var sum: Float = 0
        for i in 0 ..< buffer.count {
            sum += buffer[i]
        }
        return sum
    }
}

@derivative(of: unsafeBufferSumAD)
private func vjpUnsafeBufferSumAD(_ values: [Float]) -> (value: Float, pullback: (Float) -> [Float].TangentVector) {
    let value = unsafeBufferSumAD(values)
    return (value, { v in
        Array<Float>.DifferentiableView(repeating: v, count: values.count)
    })
}

