private func testFunc16(values: [Float]) -> Float {
    var out = values
    let idx = withoutDerivative(at: values.count / 2)
    let c16 = out[idx]
    let t0 = (c16 > 0 ? Float(-0.5634) : c16)
    let t1 = min(c16, Float(1.8355))
    let t2 = (t0 > 0 ? t1 : Float(1.4930))
    out.update(at: idx, with: t2)
    return out.differentiableReduce(Float.zero, +)
}

