@differentiable(reverse)
private func testFunc20(dict: [Int: Float]) -> Float {
    var out = dict
    let key = withoutDerivative(at: 0)
    let d20 = out[key]!
    let t0 = (d20 > 0 ? Float(0.7974) : d20)
    let t1 = abs(t0)
    out.update(at: key, with: t1)
