@differentiable(reverse)
private func testFunc141(values: [Float]) -> Float {
    var out = values
    let idx = withoutDerivative(at: values.count / 2)
    let c141 = out[idx]
    let t0 = min(c141, Float(1.1802))
    let t1 = abs(t0)
    out.update(at: idx, with: t1)
    return out.differentiableReduce(Float.zero, +)
}

