@differentiable(reverse)
private func testFunc500(values: [Float]) -> Float {
    var out = values
    let idx = withoutDerivative(at: values.count / 2)
    let c500 = out[idx]
    let t0 = min(Float(-0.7159), c500)
    out.update(at: idx, with: t0)
    return out.differentiableReduce(Float.zero, +)
}

