    var out = values
    let idx = withoutDerivative(at: values.count / 2)
    let c791 = out[idx]
    let t0 = min(c791, c791)
    let t1 = max(t0, c791)
    let t2 = abs(t1)
    out.update(at: idx, with: t2)
    return out.differentiableReduce(Float.zero, +)
}

